public readonly record struct AuthStamp(long UserId, int SchoolId);

public sealed class AttemptContext
{
    public AuthStamp Stamp { get; init; }
}

public AuthStamp OnStack(long userId, int schoolId) => new(userId, schoolId);

public object Boxed(AuthStamp stamp) => stamp;

public async Task<AuthStamp> AcrossAwaitAsync(AuthStamp stamp, CancellationToken ct)
{
    await Task.Yield();
    ct.ThrowIfCancellationRequested();
    return stamp;
}

public void ProcessToken(string token)
{
    // token is a reference on the stack pointing at a heap string object
    var bytes = token.ToCharArray(); // new char[] on the heap
    _ = bytes.Length;
}

public sealed class Session
{
    public AuthStamp Stamp; // inline inside Session object on heap
}

var session = new Session { Stamp = new AuthStamp(42, 7) };
// session ref on stack; Session + Stamp bytes on heap

Span<char> FormatId(int id)
{
    Span<char> buffer = stackalloc char[16];
    id.TryFormat(buffer, out int written);
    return buffer[..written]; // copy if escaping scope
}
